export default async function install(app){
 const [GraphicsLayer,Graphic,SketchViewModel,DistanceModel,AreaModel]=await Promise.all([app.import('esri/layers/GraphicsLayer'),app.import('esri/Graphic'),app.import('esri/widgets/Sketch/SketchViewModel'),app.import('esri/widgets/DistanceMeasurement2D/DistanceMeasurement2DViewModel'),app.import('esri/widgets/AreaMeasurement2D/AreaMeasurement2DViewModel')]);
 const mount=app.getMount('map-bottom-space');const layer=new GraphicsLayer({id:'prowise-user-sketches',title:'Schetsen'});app.map.add(layer);const measurementLayer=new GraphicsLayer({id:'prowise-measure-color',title:'Meetkleur'});app.map.add(measurementLayer);const sketch=new SketchViewModel({view:app.view,layer,updateOnGraphicClick:true});const distance=new DistanceModel({view:app.view,unit:'meters'});const area=new AreaModel({view:app.view,unit:'square-meters'});
 const style=document.createElement('style');style.textContent=`#prowise-tools-center{position:absolute;left:50%;top:8px;transform:translateX(-50%);display:flex;gap:12px;z-index:2;white-space:nowrap}#app-mount-map-bottom-space{position:relative!important}#prowise-tools-center button{font:500 14px Poppins,sans-serif;color:#154371;background:#fff;border:0;border-radius:12px;width:48px;height:48px;padding:0;cursor:pointer;display:flex;align-items:center;justify-content:center}#prowise-tools-center button svg{width:23px;height:23px;display:block;fill:none;stroke:currentColor;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}#prowise-tools-center button:hover,#prowise-tools-center button[aria-pressed=true]{background:#e5f3f2;color:#215f63}#prowise-tools-center button:focus-visible,#prowise-tools-panel button:focus-visible,#prowise-tools-panel input:focus-visible{outline:2px solid #2e7f84;outline-offset:2px}#prowise-tools-panel{position:fixed;bottom:76px;left:50%;transform:translateX(-50%);z-index:1100;width:min(380px,calc(100vw - 32px));max-height:min(440px,calc(100vh - 100px));overflow:auto;background:#fff;border-radius:32px;box-shadow:0 8px 28px rgba(0,0,0,.2);font:500 14px Poppins,sans-serif;color:#154371}#prowise-tools-panel[hidden]{display:none}#prowise-tools-panel .pw-header{display:flex;align-items:center;justify-content:space-between;background:rgb(46,127,132);color:white;padding:13px 20px;min-height:28px;font-size:18px}#prowise-tools-panel .pw-header button{background:transparent;color:white;border:0;font-size:23px;cursor:pointer}#prowise-tools-panel .pw-body{padding:18px 20px 22px}#prowise-tools-panel .pw-tools{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}#prowise-tools-panel .pw-tools button{background:#f1f6f6;color:#154371;border:1px solid #d7e6e5;border-radius:12px;padding:9px 12px;font:500 13px Poppins,sans-serif;cursor:pointer}#prowise-tools-panel .pw-tools button[aria-pressed=true]{background:#2e7f84;color:white}#prowise-tools-panel .pw-hint{color:#536c73;font-size:12px;line-height:1.5;margin:10px 0}#prowise-tools-panel .pw-reading{font-size:17px;color:#215f63;min-height:25px}#prowise-tools-panel .pw-color-row{display:flex;align-items:center;gap:12px;margin:12px 0}#prowise-tools-panel .pw-color-row input{width:44px;height:36px;padding:2px;border:1px solid #d7e6e5;border-radius:8px;background:white;cursor:pointer}`;document.head.append(style);
 const center=document.createElement('div');center.id='prowise-tools-center';center.setAttribute('role','group');center.setAttribute('aria-label','Schetsen en meten');mount.append(center);const panel=document.createElement('section');panel.id='prowise-tools-panel';panel.hidden=true;panel.setAttribute('aria-label','Kaartgereedschap');const header=document.createElement('div');header.className='pw-header';const heading=document.createElement('span');const close=document.createElement('button');close.type='button';close.textContent='×';close.title='Sluiten';close.setAttribute('aria-label','Sluiten');header.append(heading,close);const body=document.createElement('div');body.className='pw-body';panel.append(header,body);document.body.append(panel);
 let mode=null,activeTool=null,measureColor='#2e7f84',sketchColor='#2e7f84';function setSketchColor(color){sketch.pointSymbol={type:'simple-marker',style:'circle',size:10,color,outline:{color:'#fff',width:2}};sketch.polylineSymbol={type:'simple-line',color,width:3};sketch.polygonSymbol={type:'simple-fill',color:[parseInt(color.slice(1,3),16),parseInt(color.slice(3,5),16),parseInt(color.slice(5,7),16),.2],outline:{color,width:2}}}setSketchColor(sketchColor);
 function button(label,fn,parent,id){const b=document.createElement('button');b.type='button';b.textContent=label;if(id)b.id=id;b.addEventListener('click',fn);parent.append(b);return b}function iconButton(label,id,paths,fn){const b=button('',fn,center,id);b.setAttribute('aria-label',label);b.title=label;const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('aria-hidden','true');svg.setAttribute('focusable','false');for(const [tag,attrs] of paths){const el=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [key,value] of Object.entries(attrs))el.setAttribute(key,value);svg.append(el)}b.append(svg);return b}const sketchToggle=iconButton('Schetsen','footer-sketch',[['path',{d:'M4 20l4.2-1 11-11a2 2 0 0 0-3-3l-11 11L4 20z'}],['path',{d:'M14.5 6.5l3 3'}]],()=>switchMode(mode==='sketch'?null:'sketch'));const measureToggle=iconButton('Meten','footer-measure',[['path',{d:'M3 16.5L16.5 3 21 7.5 7.5 21 3 16.5z'}],['path',{d:'M13 6.5l2 2M10 9.5l2 2M7 12.5l2 2M4.5 15l2 2'}]],()=>switchMode(mode==='measure'?null:'measure'));
 function colorRow(id,label,value,onInput){const row=document.createElement('div');row.className='pw-color-row';const text=document.createElement('label');text.htmlFor=id;text.textContent=label;const picker=document.createElement('input');picker.type='color';picker.id=id;picker.value=value;picker.setAttribute('aria-label',label+' kiezen');picker.addEventListener('input',()=>onInput(picker.value));row.append(text,picker);body.append(row)}function updateMeasureGraphic(){measurementLayer.removeAll();const m=activeTool==='distance'?distance.measurement:activeTool==='area'?area.measurement:null;const geometry=m?.geometry;if(!geometry)return;const symbol=geometry.type==='polygon'?{type:'simple-fill',color:[46,127,132,0],outline:{color:measureColor,width:5}}:{type:'simple-line',color:measureColor,width:5};measurementLayer.add(new Graphic({geometry,symbol}))}function stop(){sketch.cancel();distance.clear();area.clear();measurementLayer.removeAll();activeTool=null}function switchMode(next){stop();mode=next;panel.hidden=!next;sketchToggle.setAttribute('aria-pressed',String(next==='sketch'));measureToggle.setAttribute('aria-pressed',String(next==='measure'));if(!next){body.replaceChildren();return {mode:null}}heading.textContent=next==='sketch'?'Schetsen':'Meten';body.replaceChildren();const info=document.createElement('p');info.className='pw-hint';info.textContent=next==='sketch'?'Kies een vorm en teken op de kaart. Dubbelklik om een lijn of vlak af te ronden.':'Kies afstand of oppervlakte en klik op de kaart. Dubbelklik om af te ronden.';body.append(info);const tools=document.createElement('div');tools.className='pw-tools';body.append(tools);if(next==='sketch'){colorRow('pw-sketch-color','Schetskleur',sketchColor,color=>{sketchColor=color;setSketchColor(color)});for(const [tool,label] of [['point','Punt'],['polyline','Lijn'],['polygon','Vlak'],['rectangle','Rechthoek'],['circle','Cirkel']]){const b=button(label,()=>{stop();sketch.create(tool);activeTool=tool;for(const t of tools.children)t.setAttribute('aria-pressed',String(t===b))},tools);b.setAttribute('aria-pressed','false')}const clear=button('Schetsen wissen',()=>{stop();layer.removeAll();updateCount()},body);clear.className='pw-clear';const count=document.createElement('p');count.className='pw-hint';count.id='pw-sketch-count';body.append(count);updateCount()}else{colorRow('pw-measure-color','Meetkleur',measureColor,color=>{measureColor=color;updateMeasureGraphic()});for(const [tool,label,model] of [['distance','Afstand',distance],['area','Oppervlakte',area]]){const b=button(label,()=>{stop();model.start();activeTool=tool;for(const t of tools.children)t.setAttribute('aria-pressed',String(t===b));updateReading()},tools);b.setAttribute('aria-pressed','false')}const reading=document.createElement('div');reading.className='pw-reading';reading.id='pw-measure-reading';reading.setAttribute('aria-live','polite');body.append(reading);button('Meting wissen',()=>{stop();for(const t of tools.children)t.setAttribute('aria-pressed','false');updateReading()},body);updateReading()}return {mode:next,tools:[...tools.children].map(x=>x.textContent)}}function updateCount(){const n=body.querySelector('#pw-sketch-count');if(n)n.textContent=layer.graphics.length+' schets(en) op de kaart.'}function updateReading(){const n=body.querySelector('#pw-measure-reading');if(n)n.textContent=activeTool==='distance'?(distance.measurementLabel||'Klik op de kaart om afstand te meten.'):activeTool==='area'?(area.measurementLabel||'Klik op de kaart om oppervlakte te meten.'):'Nog geen meting.'}const h1=sketch.on('create',e=>{if(e.state==='complete'){activeTool=null;updateCount()}});const h2=sketch.on('delete',updateCount);const w1=distance.watch('measurementLabel',updateReading);const w2=area.watch('measurementLabel',updateReading);const w3=distance.watch('measurement',updateMeasureGraphic);const w4=area.watch('measurement',updateMeasureGraphic);close.addEventListener('click',()=>switchMode(null));const a1=app.actions.register('open-sketch',()=>switchMode('sketch'));const a2=app.actions.register('open-measure',()=>switchMode('measure'));const a3=app.actions.register('close-drawing-tools',()=>switchMode(null));app.onCleanup(()=>{stop();h1.remove();h2.remove();w1.remove();w2.remove();w3.remove();w4.remove();a1.remove();a2.remove();a3.remove();sketch.destroy();distance.destroy();area.destroy();app.map.remove(measurementLayer);app.map.remove(layer);center.remove();panel.remove();style.remove()});return {footerButtons:[sketchToggle.id,measureToggle.id],sketchColor,measureColor,panelHidden:panel.hidden};
}